// The line recognizer - train/src/picoocr_train/model.py's network in plain JavaScript: a line input (lib/image.js
// lineInput) to per-column character scores, decoded by CTC's greedy rule (decode).
//
//     import * as recognizer from './models/recognizer.js';
//     const model = loadModel(recognizer);
//     const {text, confidence} = decode(model, forward(model, lineInput(page, box)));
//
// The model module (generated by picoocr_train.export) exports its manifest and its weights (base64). The manifest's
// layers are the network - run in order on an activation {channels, height, width, data} (Float32Array, channel-major):
//
// - conv2d - a 2-D convolution ('same' zero padding), its batch normalization folded in; relu
// - maxpool - [height, width] windows, as strides
// - flatten - the channels and rows as channels of one row (channel c, row h -> c * height + h)
// - conv1d - a 1-D convolution along the row ('same' zero padding, a dilation), its batch normalization folded in;
//   relu, and residual (the input added after the relu)
//
// The convolutions' weights are packed integers (the manifest's bits - picoocr_train/quant.py) with a float32 scale per
// output channel, dequantized on load; the biases are float32. The last layer's channels are the classes - CTC's blank
// first, then the alphabet's characters.


// The bytes of a base64 string (whitespace ignored)
export function decodeBase64(text) {
    const binary = atob(text.replace(/\s+/gu, ''));
    const bytes = new Uint8Array(binary.length);
    for (let ix = 0; ix < binary.length; ix++) {
        bytes[ix] = binary.charCodeAt(ix);
    }
    return bytes;
}


// Load a model module ({manifest, weights}) - {manifest, tensors} (each tensor a Float32Array)
export function loadModel(module) {
    const {manifest} = module;
    const {buffer} = decodeBase64(module.weights);
    const tensors = {};
    for (const entry of manifest.tensors) {
        const size = entry.shape.reduce((product, dim) => product * dim, 1);
        if (entry.dtype === 'packed') {
            tensors[entry.name] = unpackTensor(buffer, entry, size);
        } else {
            tensors[entry.name] = new Float32Array(buffer.slice(entry.offset, entry.offset + 4 * size));
        }
    }
    return {manifest, tensors};
}


// A packed tensor's weights (picoocr_train/quant.py pack) - unsigned integers of the entry's bits, little-endian bit by
// bit, offset by the width's limit, each times its row's float32 scale (float64 arithmetic, stored float32 - as
// quant.py dequantize computes them)
function unpackTensor(buffer, entry, size) {
    const {bits} = entry;
    const limit = (1 << (bits - 1)) - 1;
    const mask = (1 << bits) - 1;
    const bytes = new Uint8Array(buffer, entry.offset, Math.ceil((size * bits) / 8));
    const scales = new Float32Array(buffer.slice(entry.scaleOffset, entry.scaleOffset + 4 * entry.shape[0]));
    const rowSize = size / entry.shape[0];
    const data = new Float32Array(size);
    let bitBuffer = 0;
    let bitCount = 0;
    let byteIndex = 0;
    for (let row = 0, ix = 0; row < entry.shape[0]; row++) {
        const scale = scales[row];
        for (let column = 0; column < rowSize; column++, ix++) {
            while (bitCount < bits) {
                bitBuffer |= bytes[byteIndex] << bitCount;
                byteIndex += 1;
                bitCount += 8;
            }
            data[ix] = ((bitBuffer & mask) - limit) * scale;
            bitBuffer >>>= bits;
            bitCount -= bits;
        }
    }
    return data;
}


// The tensor of a name
function tensor(model, name) {
    const data = model.tensors[name];
    if (data === undefined) {
        throw new Error(`model tensor ${name} not found`);
    }
    return data;
}


// The shape of a manifest tensor
function tensorShape(model, name) {
    tensor(model, name);
    return model.manifest.tensors.find((entry) => entry.name === name).shape;
}


// The columns of an activation for a convolution (im2col) - a matrix [taps, positions]: each input channel's kernel
// taps (channel-major, then kernel row and column), each the activation shifted by its tap's offset (at the
// dilation), zero outside it
export function im2col(input, kernelHeight, kernelWidth, dilation) {
    const {channels, height, width, data} = input;
    const positions = height * width;
    const cols = new Float32Array(channels * kernelHeight * kernelWidth * positions);
    let tap = 0;
    for (let channel = 0; channel < channels; channel++) {
        for (let ky = 0; ky < kernelHeight; ky++) {
            const dy = (ky - (kernelHeight - 1) / 2) * dilation;
            for (let kx = 0; kx < kernelWidth; kx++, tap++) {
                const dx = (kx - (kernelWidth - 1) / 2) * dilation;
                const start = Math.max(0, -dx);
                const end = Math.min(width, width - dx);
                if (start < end) {
                    for (let row = Math.max(0, -dy); row < Math.min(height, height - dy); row++) {
                        const source = channel * positions + (row + dy) * width + dx;
                        cols.set(data.subarray(source + start, source + end), tap * positions + row * width + start);
                    }
                }
            }
        }
    }
    return cols;
}


// A matrix product plus a bias - weight [rows, depth] times cols [depth, columns], plus each row's bias - as a
// Float32Array [rows, columns]. It's computed in tiles of 8 rows and 4 columns: 32 sums, each weight and column value
// loaded once per depth step, and a step whose 4 column values are all zero skipped (a ReLU's output is often zero in
// whole regions - the paper around the text). The cost is the loads and the bytecodes - JavaScript has no SIMD, and
// without a JIT (an iPhone in Lockdown Mode) each operation is interpreted. A sum's terms are added in depth order
// (a skipped term adds exactly 0), so the result is the same as one product at a time.
export function gemm(weight, bias, cols, rows, depth, columns) {
    const output = new Float32Array(rows * columns);
    const rows8 = rows - (rows % 8);
    const columns4 = columns - (columns % 4);
    for (let row = 0; row < rows8; row += 8) {
        const w0 = row * depth;
        const w1 = w0 + depth;
        const w2 = w1 + depth;
        const w3 = w2 + depth;
        const w4 = w3 + depth;
        const w5 = w4 + depth;
        const w6 = w5 + depth;
        const w7 = w6 + depth;
        for (let column = 0; column < columns4; column += 4) {
            let s00 = bias[row], s01 = s00, s02 = s00, s03 = s00;
            let s10 = bias[row + 1], s11 = s10, s12 = s10, s13 = s10;
            let s20 = bias[row + 2], s21 = s20, s22 = s20, s23 = s20;
            let s30 = bias[row + 3], s31 = s30, s32 = s30, s33 = s30;
            let s40 = bias[row + 4], s41 = s40, s42 = s40, s43 = s40;
            let s50 = bias[row + 5], s51 = s50, s52 = s50, s53 = s50;
            let s60 = bias[row + 6], s61 = s60, s62 = s60, s63 = s60;
            let s70 = bias[row + 7], s71 = s70, s72 = s70, s73 = s70;
            for (let ix = 0, col = column; ix < depth; ix++, col += columns) {
                const c0 = cols[col];
                const c1 = cols[col + 1];
                const c2 = cols[col + 2];
                const c3 = cols[col + 3];
                if (c0 === 0 && c1 === 0 && c2 === 0 && c3 === 0) {
                    continue;
                }
                let value = weight[w0 + ix];
                s00 += value * c0;
                s01 += value * c1;
                s02 += value * c2;
                s03 += value * c3;
                value = weight[w1 + ix];
                s10 += value * c0;
                s11 += value * c1;
                s12 += value * c2;
                s13 += value * c3;
                value = weight[w2 + ix];
                s20 += value * c0;
                s21 += value * c1;
                s22 += value * c2;
                s23 += value * c3;
                value = weight[w3 + ix];
                s30 += value * c0;
                s31 += value * c1;
                s32 += value * c2;
                s33 += value * c3;
                value = weight[w4 + ix];
                s40 += value * c0;
                s41 += value * c1;
                s42 += value * c2;
                s43 += value * c3;
                value = weight[w5 + ix];
                s50 += value * c0;
                s51 += value * c1;
                s52 += value * c2;
                s53 += value * c3;
                value = weight[w6 + ix];
                s60 += value * c0;
                s61 += value * c1;
                s62 += value * c2;
                s63 += value * c3;
                value = weight[w7 + ix];
                s70 += value * c0;
                s71 += value * c1;
                s72 += value * c2;
                s73 += value * c3;
            }
            let out = row * columns + column;
            output[out] = s00;
            output[out + 1] = s01;
            output[out + 2] = s02;
            output[out + 3] = s03;
            out += columns;
            output[out] = s10;
            output[out + 1] = s11;
            output[out + 2] = s12;
            output[out + 3] = s13;
            out += columns;
            output[out] = s20;
            output[out + 1] = s21;
            output[out + 2] = s22;
            output[out + 3] = s23;
            out += columns;
            output[out] = s30;
            output[out + 1] = s31;
            output[out + 2] = s32;
            output[out + 3] = s33;
            out += columns;
            output[out] = s40;
            output[out + 1] = s41;
            output[out + 2] = s42;
            output[out + 3] = s43;
            out += columns;
            output[out] = s50;
            output[out + 1] = s51;
            output[out + 2] = s52;
            output[out + 3] = s53;
            out += columns;
            output[out] = s60;
            output[out + 1] = s61;
            output[out + 2] = s62;
            output[out + 3] = s63;
            out += columns;
            output[out] = s70;
            output[out + 1] = s71;
            output[out + 2] = s72;
            output[out + 3] = s73;
        }

        // The remainder columns, a column at a time
        for (let column = columns4; column < columns; column++) {
            for (let tileRow = 0; tileRow < 8; tileRow++) {
                const outRow = row + tileRow;
                output[outRow * columns + column] = dot(weight, outRow * depth, bias[outRow], cols, column, depth, columns);
            }
        }
    }

    // The remainder rows, a value at a time
    for (let row = rows8; row < rows; row++) {
        for (let column = 0; column < columns; column++) {
            output[row * columns + column] = dot(weight, row * depth, bias[row], cols, column, depth, columns);
        }
    }
    return output;
}


// A weight row's product with a column of cols, plus a bias
function dot(weight, weightBase, bias, cols, column, depth, columns) {
    let sum = bias;
    for (let ix = 0, col = column; ix < depth; ix++, col += columns) {
        sum += weight[weightBase + ix] * cols[col];
    }
    return sum;
}


// A convolution layer ('same' zero padding) - weight [out, in, kernelHeight, kernelWidth] (conv2d) or [out, in,
// kernelWidth] (conv1d, along a one-row activation, at the layer's dilation) - as im2col and a matrix product (a 1x1
// convolution's columns are its input); relu, and residual (the input added after the relu)
function convolution(model, layer, input, shape) {
    const [outChannels, inChannels] = shape;
    const [kernelHeight, kernelWidth] = shape.length === 4 ? shape.slice(2) : [1, shape[2]];
    const positions = input.height * input.width;
    const cols = kernelHeight * kernelWidth === 1 ? input.data : im2col(input, kernelHeight, kernelWidth, layer.dilation ?? 1);
    const weight = tensor(model, `${layer.name}.weight`);
    const data = gemm(weight, tensor(model, `${layer.name}.bias`), cols, outChannels, inChannels * kernelHeight * kernelWidth, positions);
    if (layer.relu) {
        relu(data);
    }
    if (layer.residual) {
        for (let ix = 0; ix < data.length; ix++) {
            data[ix] += input.data[ix];
        }
    }
    return {'channels': outChannels, 'height': input.height, 'width': input.width, data};
}


// A 2-D convolution - weight [out, in, kernel, kernel]
export function conv2d(model, layer, input) {
    const shape = tensorShape(model, `${layer.name}.weight`);
    if (shape[1] !== input.channels) {
        throw new Error(`layer ${layer.name} expects ${shape[1]} channels, got ${input.channels}`);
    }
    return convolution(model, layer, input, shape);
}


// A 1-D convolution along a one-row activation - weight [out, in, kernel]
export function conv1d(model, layer, input) {
    const shape = tensorShape(model, `${layer.name}.weight`);
    if (shape[1] !== input.channels || input.height !== 1) {
        throw new Error(`layer ${layer.name} expects ${shape[1]} channels of one row`);
    }
    return convolution(model, layer, input, shape);
}


// Rectify values in place
function relu(data) {
    for (let ix = 0; ix < data.length; ix++) {
        if (data[ix] < 0) {
            data[ix] = 0;
        }
    }
}


// Max pooling over [height, width] windows (as strides - the remainder rows and columns dropped)
export function maxpool(layer, input) {
    const [poolHeight, poolWidth] = layer.size;
    const height = Math.floor(input.height / poolHeight);
    const width = Math.floor(input.width / poolWidth);
    const output = {'channels': input.channels, height, width, 'data': new Float32Array(input.channels * height * width)};
    for (let channel = 0; channel < input.channels; channel++) {
        const inBase = channel * input.height * input.width;
        const outBase = channel * height * width;
        for (let row = 0; row < height; row++) {
            for (let column = 0; column < width; column++) {
                let max = -Infinity;
                for (let py = 0; py < poolHeight; py++) {
                    const inRow = inBase + (row * poolHeight + py) * input.width + column * poolWidth;
                    for (let px = 0; px < poolWidth; px++) {
                        const value = input.data[inRow + px];
                        if (value > max) {
                            max = value;
                        }
                    }
                }
                output.data[outBase + row * width + column] = max;
            }
        }
    }
    return output;
}


// The network's class scores for a line input (lib/image.js lineInput) - {classes, steps, data} (Float32Array,
// class-major: data[class * steps + step])
export function forward(model, line) {
    let activation = {'channels': 1, 'height': line.height, 'width': line.width, 'data': line.data};
    for (const layer of model.manifest.layers) {
        if (layer.op === 'conv2d') {
            activation = conv2d(model, layer, activation);
        } else if (layer.op === 'maxpool') {
            activation = maxpool(layer, activation);
        } else if (layer.op === 'flatten') {
            const {channels, height, width, data} = activation;
            activation = {'channels': channels * height, 'height': 1, width, data};
        } else if (layer.op === 'conv1d') {
            activation = conv1d(model, layer, activation);
        } else {
            throw new Error(`unknown layer op ${layer.op}`);
        }
    }
    return {'classes': activation.channels, 'steps': activation.width, 'data': activation.data};
}


// The text of class scores by CTC's greedy rule - each step's best class, repeats collapsed, blanks dropped - and its
// confidence: the mean probability of the characters' steps (1 if none)
export function decode(model, scores) {
    const {alphabet} = model.manifest;
    const {classes, steps, data} = scores;
    let text = '';
    let previous = 0;
    let probabilitySum = 0;
    let characters = 0;
    for (let step = 0; step < steps; step++) {
        let best = 0;
        let bestScore = data[step];
        for (let cls = 1; cls < classes; cls++) {
            if (data[cls * steps + step] > bestScore) {
                best = cls;
                bestScore = data[cls * steps + step];
            }
        }
        if (best !== 0 && best !== previous) {
            let total = 0;
            for (let cls = 0; cls < classes; cls++) {
                total += Math.exp(data[cls * steps + step] - bestScore);
            }
            text += alphabet[best - 1];
            probabilitySum += 1 / total;
            characters += 1;
        }
        previous = best;
    }
    return {text, 'confidence': characters === 0 ? 1 : probabilitySum / characters};
}


// The network's confidence in a line - the mean, over its steps from one to another (all, by default), of the best
// class's probability (blanks included - a line read as nothing is no surer than it's read)
export function meanConfidence(scores, from = 0, to = scores.steps) {
    const {classes, steps, data} = scores;
    let sum = 0;
    for (let step = from; step < to; step++) {
        let best = data[step];
        for (let cls = 1; cls < classes; cls++) {
            best = Math.max(best, data[cls * steps + step]);
        }
        let total = 0;
        for (let cls = 0; cls < classes; cls++) {
            total += Math.exp(data[cls * steps + step] - best);
        }
        sum += 1 / total;
    }
    return to > from ? sum / (to - from) : 0;
}
